#!/usr/bin/env python3
import sys, time

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == 'uci':
            sys.stdout.write('id name FakeEngine\n')
            sys.stdout.write('id author Test\n')
            sys.stdout.write('uciok\n')
            sys.stdout.flush()
        elif line == 'isready':
            sys.stdout.write('readyok\n')
            sys.stdout.flush()
        elif line.startswith('setoption'):
            # ignore
            pass
        elif line == 'ucinewgame':
            pass
        elif line.startswith('position'):
            pass
        elif line.startswith('go'):
            # send a big negative score from White's perspective, bestmove 0000
            sys.stdout.write('info score cp -1000\n')
            sys.stdout.write('bestmove 0000\n')
            sys.stdout.flush()
        elif line == 'quit':
            break
    sys.exit(0)

if __name__ == '__main__':
    main()
